import{_ as a}from"./chunks/flight_termination_logic_diagram.BoO2W-Fs.js";import{_ as t,c as i,o,al as r}from"./chunks/framework.CT7RwC5a.js";const u=JSON.parse('{"title":"Flight Termination Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/advanced_config/flight_termination.md","filePath":"en/advanced_config/flight_termination.md"}'),n={name:"en/advanced_config/flight_termination.md"};function l(s,e,c,h,f,m){return o(),i("div",null,e[0]||(e[0]=[r('<h1 id="flight-termination-configuration" tabindex="-1">Flight Termination Configuration <a class="header-anchor" href="#flight-termination-configuration" aria-label="Permalink to &quot;Flight Termination Configuration&quot;">​</a></h1><p>The <em>Flight termination</em> <a href="./../config/safety.html#failsafe-actions">failsafe action</a> irreversibly turns off controllers and sets PWM values to their parameter configured failsafe values.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Flight termination differs from the <a href="./../config/safety.html#kill-switch">Kill action</a> in that it is permanent until after reboot.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is <em>not</em> an independent <em>Flight Termination System</em>. If power is lost or if the autopilot crashes completely, the failsafe devices will not be triggered.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><h3 id="termination-triggers" tabindex="-1">Termination Triggers <a class="header-anchor" href="#termination-triggers" aria-label="Permalink to &quot;Termination Triggers&quot;">​</a></h3><p>Termination may be triggered by:</p><ul><li><a href="./../config/safety.html">Safety checks</a> for RC Loss, geofence violation, and so on (on any vehicle type or in any flight mode).</li><li><a href="./../config/safety.html#failure-detector">Failure Detector</a> trigger</li><li>RC termination switch (mapped to an RC channel using <a href="./../advanced_config/parameter_reference.html#RC_MAP_TERM_SW">RC_MAP_TERM_SW</a>).</li><li>The MAVLink <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_FLIGHTTERMINATION" target="_blank" rel="noreferrer">MAV_CMD_DO_FLIGHTTERMINATION</a> MAVLink command from a GCS or companion computer (see <a href="#mavlink-trigger">MAVLink Trigger</a> below).</li></ul><p>There is no way to recover from flight termination. After triggering you should unplug the battery as soon as possible. You will need to reboot/power cycle the vehicle before it can be used again.</p><h3 id="termination-actions" tabindex="-1">Termination Actions <a class="header-anchor" href="#termination-actions" aria-label="Permalink to &quot;Termination Actions&quot;">​</a></h3><p>When <em>Flight termination</em> is activated, PX4 simultaneously turns off all controllers and sets all PWM outputs to their failsafe values.</p><p>Depending on what devices are connected, the PWM failsafe outputs can be used to:</p><ul><li>Deploy a <a href="./../peripherals/parachute.html">parachute</a>.</li><li>Extend retractable landing gear.</li><li>Move a PWM-connected gimbal to a safe orientation (or retract it) in order to protect the camera.</li><li>Trigger an inflatable device like an airbag.</li><li>Trigger an alarm.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>PX4 does not know what safety devices are attached - it just applies a predefined set of PWM values to its outputs.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Failsafe values are applied to all outputs on termination. There is no way to configure independent time-based (or other) triggering of the motors or specific safety devices.</p></div><h2 id="hardware-configuration" tabindex="-1">Hardware Configuration <a class="header-anchor" href="#hardware-configuration" aria-label="Permalink to &quot;Hardware Configuration&quot;">​</a></h2><p>Any <em>safety device(s)</em> (e.g. a <a href="./../peripherals/parachute.html">parachute</a>) that can be triggered by changing a PWM value can be used, and may be connected to any free PWM port (both MAIN and AUX).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you&#39;re using Pixhawk-series board you will have to separately power the servo rail (i.e. from a 5V BEC, which is often also available from your ESC).</p></div><h2 id="software-configuration" tabindex="-1">Software Configuration <a class="header-anchor" href="#software-configuration" aria-label="Permalink to &quot;Software Configuration&quot;">​</a></h2><p>The <a href="./../config/safety.html">Safety</a> topic explains how to set the <em>flight termination</em> as the <a href="./../config/safety.html#failsafe-actions">failsafe action</a> to be performed for particular failsafe check.</p><p>The <a href="./../config/safety.html#failure-detector">Failure Detector</a> can also (optionally) be configured to trigger flight termination if the vehicle flips (exceeds a certain attitude) or if failure is detected by an external automatic trigger system (ATS):</p><ul><li>Enable the failure detector during flight by setting <a href="./../advanced_config/parameter_reference.html#CBRK_FLIGHTTERM">CBRK_FLIGHTTERM=0</a>.</li><li><a href="./../config/safety.html#attitude-trigger">Safety &gt; Failure Detector &gt; Attitude Trigger</a> explains how to configure the attitude limits that trigger <em>Flight termination</em>.<div class="info custom-block"><p class="custom-block-title">INFO</p><p>During <em>takeoff</em> excessive attitutes will trigger <em>lockdown</em> (kill motors, but not launch parachute) rather than flight termination. This is always enabled, irrespective of the value of <code>CBRK_FLIGHTTERM</code>.</p></div></li><li><a href="./../config/safety.html#external-automatic-trigger-system-ats">Safety &gt; External Automatic Trigger System (ATS)</a> explains how to configure an external trigger system.</li></ul><p>For each MAIN output to which a safety device is attached, where &quot;n&quot; is the PWM port number, set:</p><ul><li><a href="./../advanced_config/parameter_reference.html#PWM_MAIN_DIS1">PWM_MAIN_DISn</a> to the device&#39;s &quot;OFF&quot; PWM value.</li><li><a href="./../advanced_config/parameter_reference.html#PWM_MAIN_FAIL1">PWM_MAIN_FAILn</a> to the device&#39;s &quot;ON&quot; PWM value.</li></ul><p>For each AUX output to which a safety device is attached, where &quot;n&quot; is the PWM port number, set:</p><ul><li><a href="./../advanced_config/parameter_reference.html#PWM_AUX_DIS1">PWM_AUX_DIS1</a> to the device&#39;s &quot;OFF&quot; PWM value.</li><li><a href="./../advanced_config/parameter_reference.html#PWM_AUX_FAIL1">PWM_AUX_FAILn</a> to the device&#39;s &quot;ON&quot; PWM value.</li></ul><p>Finally, set the <code>PWM_AUX_FAILn</code> and <code>PWM_MAIN_FAILn</code> PWM values for any motors.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Flight termination via ATS only works if <code>drivers/pwm_input</code> is included in the firmware for your board. If not, you need to add it manually to your board configuration using <a href="./../hardware/porting_guide_config.html#px4-menuconfig-setup">boardconfig</a>.</p></div><h2 id="mavlink-trigger" tabindex="-1">MAVLink Trigger <a class="header-anchor" href="#mavlink-trigger" aria-label="Permalink to &quot;MAVLink Trigger&quot;">​</a></h2><p>The <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_FLIGHTTERMINATION" target="_blank" rel="noreferrer">MAV_CMD_DO_FLIGHTTERMINATION</a> command can be used to trigger Flight termination from a ground station or companion computer.</p><p>This is sent, for example, when you call the <a href="https://mavsdk.mavlink.io/main/en/cpp/api_reference/classmavsdk_1_1_action.html#classmavsdk_1_1_action_1a47536c4a4bc8367ccd30a92eb09781c5" target="_blank" rel="noreferrer">MAVSDK Action plugin</a> <code>terminate()</code> or <code>terminate_async()</code> methods.</p><h2 id="logic-diagram" tabindex="-1">Logic Diagram <a class="header-anchor" href="#logic-diagram" aria-label="Permalink to &quot;Logic Diagram&quot;">​</a></h2><p>The diagram below shows the logical flow around flight termination.</p><p><img src="'+a+'" alt="Logic diagram"></p>',34)]))}const p=t(n,[["render",l]]);export{u as __pageData,p as default};
